create table public.aparelhos ("id" bigint generated always as identity not null, "cliente_id" bigint not null, "marca" text not null, "modelo" text not null, "cor" text, "imei" text, "observacoes" text, "criado_em" timestamp with time zone default now() not null);
create table public.clientes ("id" bigint generated always as identity not null, "nome" text not null, "telefone" text not null, "email" text, "cpf" text, "observacoes" text, "criado_em" timestamp with time zone default now() not null);
create table public.estoque ("loja_id" bigint not null, "produto_id" bigint not null, "quantidade" integer default 0 not null, "estoque_minimo" integer default 0 not null, "atualizado_em" timestamp with time zone default now() not null);
create table public.fornecedores ("id" bigint generated always as identity not null, "nome" text not null, "telefone" text, "email" text, "cnpj" text, "observacoes" text, "ativo" boolean default true not null, "criado_em" timestamp with time zone default now() not null);
create table public.funcionarios ("id" bigint generated always as identity not null, "nome" text not null, "ativo" boolean default true not null, "criado_em" timestamp with time zone default now() not null);
create table public.itens_ordem_servico ("id" bigint generated always as identity not null, "ordem_servico_id" bigint not null, "produto_id" bigint not null, "quantidade" integer not null, "valor_unitario" numeric not null, "criado_em" timestamp with time zone default now() not null);
create table public.itens_transferencia ("id" bigint generated always as identity not null, "transferencia_id" bigint not null, "produto_id" bigint not null, "quantidade" integer not null, "criado_em" timestamp with time zone default now() not null);
create table public.lojas ("id" bigint generated always as identity not null, "nome" text not null, "endereco" text not null, "ativo" boolean default true not null, "criado_em" timestamp with time zone default now() not null);
create table public.mensagens_whatsapp ("id" bigint generated always as identity not null, "ordem_servico_id" bigint not null, "telefone_destino" text not null, "tipo" text not null, "mensagem" text not null, "status_envio" text default 'pendente'::text not null, "id_mensagem_externa" text, "criado_em" timestamp with time zone default now() not null, "enviado_em" timestamp with time zone);
create table public.movimentacoes_estoque ("id" bigint generated always as identity not null, "loja_id" bigint not null, "produto_id" bigint not null, "funcionario_id" bigint not null, "ordem_servico_id" bigint, "transferencia_id" bigint, "tipo" text not null, "quantidade" integer not null, "observacoes" text, "criado_em" timestamp with time zone default now() not null);
create table public.ordens_servico ("id" bigint generated always as identity not null, "loja_id" bigint not null, "cliente_id" bigint not null, "aparelho_id" bigint not null, "funcionario_id" bigint not null, "telefone_contato" text not null, "nome_contato" text, "autoriza_whatsapp" boolean default false not null, "defeito_relatado" text not null, "diagnostico" text, "status" text default 'aguardando_avaliacao'::text not null, "status_orcamento" text default 'nao_enviado'::text not null, "data_aprovacao" timestamp with time zone, "valor_pecas" numeric default 0 not null, "valor_mao_obra" numeric default 0 not null, "desconto" numeric default 0 not null, "data_entrada" timestamp with time zone default now() not null, "data_conclusao" timestamp with time zone, "data_entrega" timestamp with time zone, "observacoes" text, "criado_em" timestamp with time zone default now() not null);
create table public.produtos ("id" bigint generated always as identity not null, "nome" text not null, "categoria" text not null, "marca" text, "modelo_compativel" text, "fornecedor_id" bigint, "preco_custo" numeric default 0 not null, "preco_venda" numeric default 0 not null, "ativo" boolean default true not null, "criado_em" timestamp with time zone default now() not null);
create table public.transferencias ("id" bigint generated always as identity not null, "loja_origem_id" bigint not null, "loja_destino_id" bigint not null, "funcionario_id" bigint not null, "status" text default 'pendente'::text not null, "observacoes" text, "criado_em" timestamp with time zone default now() not null, "enviado_em" timestamp with time zone, "recebido_em" timestamp with time zone);
alter table public.aparelhos add constraint aparelhos_imei_key UNIQUE (imei);
alter table public.aparelhos add constraint aparelhos_marca_check CHECK ((length(TRIM(BOTH FROM marca)) > 0));
alter table public.aparelhos add constraint aparelhos_modelo_check CHECK ((length(TRIM(BOTH FROM modelo)) > 0));
alter table public.aparelhos add constraint aparelhos_pkey PRIMARY KEY (id);
alter table public.clientes add constraint clientes_cpf_key UNIQUE (cpf);
alter table public.clientes add constraint clientes_nome_check CHECK ((length(TRIM(BOTH FROM nome)) > 0));
alter table public.clientes add constraint clientes_pkey PRIMARY KEY (id);
alter table public.clientes add constraint clientes_telefone_check CHECK ((length(TRIM(BOTH FROM telefone)) > 0));
alter table public.estoque add constraint estoque_estoque_minimo_check CHECK ((estoque_minimo >= 0));
alter table public.estoque add constraint estoque_pkey PRIMARY KEY (loja_id, produto_id);
alter table public.estoque add constraint estoque_quantidade_check CHECK ((quantidade >= 0));
alter table public.fornecedores add constraint fornecedores_cnpj_key UNIQUE (cnpj);
alter table public.fornecedores add constraint fornecedores_nome_check CHECK ((length(TRIM(BOTH FROM nome)) > 0));
alter table public.fornecedores add constraint fornecedores_pkey PRIMARY KEY (id);
alter table public.funcionarios add constraint funcionarios_nome_check CHECK ((length(TRIM(BOTH FROM nome)) > 0));
alter table public.funcionarios add constraint funcionarios_pkey PRIMARY KEY (id);
alter table public.itens_ordem_servico add constraint itens_ordem_servico_pkey PRIMARY KEY (id);
alter table public.itens_ordem_servico add constraint itens_ordem_servico_quantidade_check CHECK ((quantidade > 0));
alter table public.itens_ordem_servico add constraint itens_ordem_servico_valor_unitario_check CHECK ((valor_unitario >= (0)::numeric));
alter table public.itens_transferencia add constraint itens_transferencia_pkey PRIMARY KEY (id);
alter table public.itens_transferencia add constraint itens_transferencia_quantidade_check CHECK ((quantidade > 0));
alter table public.itens_transferencia add constraint itens_transferencia_transferencia_id_produto_id_key UNIQUE (transferencia_id, produto_id);
alter table public.lojas add constraint lojas_endereco_check CHECK ((length(TRIM(BOTH FROM endereco)) > 0));
alter table public.lojas add constraint lojas_nome_check CHECK ((length(TRIM(BOTH FROM nome)) > 0));
alter table public.lojas add constraint lojas_pkey PRIMARY KEY (id);
alter table public.mensagens_whatsapp add constraint mensagens_whatsapp_mensagem_check CHECK ((length(TRIM(BOTH FROM mensagem)) > 0));
alter table public.mensagens_whatsapp add constraint mensagens_whatsapp_pkey PRIMARY KEY (id);
alter table public.mensagens_whatsapp add constraint mensagens_whatsapp_status_envio_check CHECK ((status_envio = ANY (ARRAY['pendente'::text, 'enviada'::text, 'entregue'::text, 'lida'::text, 'falha'::text])));
alter table public.mensagens_whatsapp add constraint mensagens_whatsapp_telefone_destino_check CHECK ((length(TRIM(BOTH FROM telefone_destino)) > 0));
alter table public.mensagens_whatsapp add constraint mensagens_whatsapp_tipo_check CHECK ((tipo = ANY (ARRAY['os_criada'::text, 'orcamento_disponivel'::text, 'orcamento_aprovado'::text, 'status_atualizado'::text, 'servico_concluido'::text, 'aviso_retirada'::text, 'mensagem_manual'::text])));
alter table public.movimentacoes_estoque add constraint movimentacoes_estoque_pkey PRIMARY KEY (id);
alter table public.movimentacoes_estoque add constraint movimentacoes_estoque_quantidade_check CHECK ((quantidade > 0));
alter table public.movimentacoes_estoque add constraint movimentacoes_estoque_tipo_check CHECK ((tipo = ANY (ARRAY['entrada'::text, 'saida'::text, 'ajuste_entrada'::text, 'ajuste_saida'::text, 'uso_os'::text, 'transferencia_envio'::text, 'transferencia_recebimento'::text])));
alter table public.ordens_servico add constraint ordens_servico_defeito_relatado_check CHECK ((length(TRIM(BOTH FROM defeito_relatado)) > 0));
alter table public.ordens_servico add constraint ordens_servico_desconto_check CHECK ((desconto >= (0)::numeric));
alter table public.ordens_servico add constraint ordens_servico_pkey PRIMARY KEY (id);
alter table public.ordens_servico add constraint ordens_servico_status_check CHECK ((status = ANY (ARRAY['aguardando_avaliacao'::text, 'aguardando_aprovacao'::text, 'aprovado'::text, 'em_andamento'::text, 'concluido'::text, 'entregue'::text, 'cancelado'::text])));
alter table public.ordens_servico add constraint ordens_servico_status_orcamento_check CHECK ((status_orcamento = ANY (ARRAY['nao_enviado'::text, 'aguardando_aprovacao'::text, 'aprovado'::text, 'recusado'::text])));
alter table public.ordens_servico add constraint ordens_servico_telefone_contato_check CHECK ((length(TRIM(BOTH FROM telefone_contato)) > 0));
alter table public.ordens_servico add constraint ordens_servico_valor_mao_obra_check CHECK ((valor_mao_obra >= (0)::numeric));
alter table public.ordens_servico add constraint ordens_servico_valor_pecas_check CHECK ((valor_pecas >= (0)::numeric));
alter table public.produtos add constraint produtos_categoria_check CHECK ((length(TRIM(BOTH FROM categoria)) > 0));
alter table public.produtos add constraint produtos_nome_check CHECK ((length(TRIM(BOTH FROM nome)) > 0));
alter table public.produtos add constraint produtos_pkey PRIMARY KEY (id);
alter table public.produtos add constraint produtos_preco_custo_check CHECK ((preco_custo >= (0)::numeric));
alter table public.produtos add constraint produtos_preco_venda_check CHECK ((preco_venda >= (0)::numeric));
alter table public.transferencias add constraint transferencias_check CHECK ((loja_origem_id <> loja_destino_id));
alter table public.transferencias add constraint transferencias_pkey PRIMARY KEY (id);
alter table public.transferencias add constraint transferencias_status_check CHECK ((status = ANY (ARRAY['pendente'::text, 'enviada'::text, 'recebida'::text, 'cancelada'::text])));
alter table public.aparelhos add constraint aparelhos_cliente_id_fkey FOREIGN KEY (cliente_id) REFERENCES clientes(id);
